const t=JSON.parse(await tools.read_task_input({id:"target-selection.json",pointer:"/full_target"}));store("fullTarget",t.value);
const B=(symbol,type)=>({symbol,type});
const D=(id,symbol,type,definition,depends_on=[],objects=[],binders=[],requires=[])=>({id,symbol,type,definition,depends_on,requires,binders,objects});
const defs=[
D("D001","V","real Euclidean vector space with measure","V=R^n, realized as tuples (x_1,...,x_n). Its topology is the Euclidean topology and its measure dx is the product of n one-dimensional Lebesgue measures. Compactness, continuity and derivatives use these topologies; integrable means Lebesgue absolutely integrable.",[],["n"]),
D("D002","W","real Euclidean vector space","W=R^m with inner product v·w=sum_{k=1}^m v_k w_k and norm |v|=(sum_{k=1}^m v_k^2)^(1/2). On V the same convention uses n coordinates. The squared norm and dot product in all formulas have this meaning.",[],["m","n"],[B("v","vector in W"),B("w","vector in W")]),
D("D003","u_t","function V×(0,∞)→W","u_t(x,r) is the derivative at r of the one-variable map ρ↦u(x,ρ). Derivatives are ordinary Fréchet derivatives in coordinate directions; outside their differentiability set use the total derivative convention zero. This convention grants no differentiability.",["D001","D002"],["u","V","W"],[B("x","point of V"),B("r","positive real")]),
D("D004","u_tt","function V×(0,∞)→W","u_tt(x,r)=∂_r u_t(x,r).",["D003"],["u_t"],[B("x","point of V"),B("r","positive real")]),
D("D005","u_j","family indexed by j=1,...,n of functions V×(0,∞)→W","u_j(x,r)=∂_{x_j}u(x,r), the coordinate derivative in the jth spatial direction.",["D001","D002"],["u","n","V","W"],[B("j","integer with 1≤j≤n"),B("x","point of V"),B("r","positive real")]),
D("D006","u_jj","family indexed by j=1,...,n of functions V×(0,∞)→W","u_jj(x,r)=∂_{x_j}u_j(x,r).",["D005"],["u_j","n"],[B("j","integer with 1≤j≤n"),B("x","point of V"),B("r","positive real")]),
D("D007","u_jt","family indexed by j=1,...,n of functions V×(0,∞)→W","u_jt(x,r)=∂_{x_j}u_t(x,r). Commutation with ∂_r u_j is a claim to be proved, not part of this definition.",["D003","D005"],["u_t","n"],[B("j","integer with 1≤j≤n"),B("x","point of V"),B("r","positive real")]),
D("D008","Δu","function V×(0,∞)→W","Δu(x,r)=sum_{j=1}^n u_jj(x,r), component by component. The gradient D_x u has columns u_j; its Frobenius square is sum_{j=1}^n |u_j|^2.",["D006","D002"],["u_jj","u_j","n"],[B("x","point of V"),B("r","positive real")]),
D("D009","e","function V×(0,∞)→R","e(x,r)=|u_t(x,r)|^2+sum_{j=1}^n |u_j(x,r)|^2.",["D003","D005","D002"],["u_t","u_j","n"],[B("x","point of V"),B("r","positive real")]),
D("D010","e_t","function V×(0,∞)→R","e_t(x,r)=∂_r e(x,r), with the total derivative convention of D003.",["D009"],["e"],[B("x","point of V"),B("r","positive real")]),
D("D011","A","function V×(0,∞)→R","A(x,r)=u_t(x,r)·u_tt(x,r).",["D003","D004","D002"],["u_t","u_tt"],[B("x","point of V"),B("r","positive real")]),
D("D012","B","family indexed by j=1,...,n of real functions V×(0,∞)","B_j(x,r)=u_j(x,r)·u_jt(x,r). The symbol B denotes this whole family, not a bound constant.",["D005","D007","D002"],["u_j","u_jt","n"],[B("j","integer with 1≤j≤n"),B("x","point of V"),B("r","positive real")]),
D("D013","T","family indexed by j=1,...,n of real functions V×(0,∞)","T_j(x,r)=u_t(x,r)·u_jj(x,r).",["D003","D006","D002"],["u_t","u_jj","n"],[B("j","integer with 1≤j≤n"),B("x","point of V"),B("r","positive real")]),
D("D014","g","family indexed by j=1,...,n of real functions V×(0,∞)","g_j(x,r)=u_t(x,r)·u_j(x,r).",["D003","D005","D002"],["u_t","u_j","n"],[B("j","integer with 1≤j≤n"),B("x","point of V"),B("r","positive real")]),
D("D015","E","function (0,∞)→R","E(r)=∫_V e(x,r) dx, the actual finite Lebesgue integral. Existence and absolute integrability at every positive time are supplied by N002.",["D001","D009"],["e","V"],[B("r","positive real")],["N002"])
];
const hs=[
{id:"H001",statement:"n and m are integers with n≥1 and m≥1 (represented as natural-number dimensions).",origin:"problem.md:25-26"},
{id:"H002",statement:"u:R^n×(0,∞)→R^m is jointly smooth: every finite-order coordinate partial derivative exists and is continuous on this open domain.",origin:"problem.md:25-26"},
{id:"H003",statement:"q∈R^m is fixed and |q|=1.",origin:"problem.md:27"},
{id:"H004",statement:"For every x∈R^n and every r>0, |u(x,r)|=1.",origin:"problem.md:29"},
{id:"H005",statement:"For every x∈R^n and every r>0 there exists a real scalar a with u_tt(x,r)−Δu(x,r)=a u(x,r). No regularity or globally chosen scalar field is assumed.",origin:"problem.md:30-33"},
{id:"H006",statement:"For every pair of real numbers 0<s<t<∞ there exists a compact set C_[s,t]⊂R^n such that u(x,r)=q for every x∉C_[s,t] and every r∈[s,t].",origin:"problem.md:34-36"}
];
const artifact={spec:{format_version:2,case_id:"wave-map-energy",full_target:load("fullTarget"),conclusion:"For every r>0 the function x↦e(x,r) is Lebesgue integrable on V; E is differentiable on (0,∞), and E'(r)=0 for every r>0. In particular E(s)=E(t) for all s,t>0. The energy is ∫_V (|u_t|^2+sum_{j=1}^n|u_j|^2) dx, with no factor 1/2 and no assertion at time zero.",parameters:[B("n","natural number used as an integer dimension"),B("m","natural number used as an integer dimension"),B("u","function R^n×(0,∞)→R^m"),B("q","vector in R^m")],hypotheses:hs,definitions:defs,logic:{classical:true,rules:["direct","forall_introduction","exists_elimination","implication_introduction","case_elimination"]},pins:{},inputs:[]},graph:{format_version:2,case_id:"wave-map-energy",spec_sha256:"controller-bound",propositions:[],inferences:[]}};
store("artifact",artifact);text("Specification and definitions constructed.");

const a=load("artifact");const bind=(symbol,type)=>({symbol,type});
function prop(id,kind,statement,definitions,binders,objects,extra={}){return {id,kind,statement,definitions,binders,objects,...extra}}
a.graph.propositions=[
prop("H001","hypothesis",a.spec.hypotheses[0].statement,[],[],["n","m"]),
