prop("H005","hypothesis",a.spec.hypotheses[4].statement,["D003","D004","D008"],[bind("x","point of V"),bind("r","positive real"),bind("a","real scalar, existential at (x,r)")],["u","u_tt","Δu","x","r","a"]),
prop("H006","hypothesis",a.spec.hypotheses[5].statement,["D001","D002"],[bind("s","real"),bind("t","real"),bind("C_[s,t]","existential compact subset of V"),bind("x","point of V"),bind("r","real")],["u","q","n","s","t","C_[s,t]","x","r"])
];
const M=(id,declaration,statement,binders,hypotheses)=>prop(id,"mathlib",statement,[],binders,binders.map(b=>b.symbol),{source:{declaration,hypotheses}});
const b=bind;
a.graph.propositions.push(
M("M001","HasDerivAt.mul","For any nontrivially normed field 𝕜, normed ring Z with a normed 𝕜-algebra structure, maps φ,ψ:𝕜→Z, point z∈𝕜 and vectors φ',ψ'∈Z: if φ has derivative φ' at z and ψ has derivative ψ' at z, then their pointwise product has derivative φ' ψ(z)+φ(z) ψ' at z. Here having derivative is the usual first-order difference-quotient limit.",[b("𝕜","nontrivially normed field"),b("Z","normed ring and normed algebra over 𝕜"),b("φ","map 𝕜→Z"),b("ψ","map 𝕜→Z"),b("z","point of 𝕜"),b("φ'","element of Z"),b("ψ'","element of Z")],["𝕜 is a nontrivially normed field; Z is a normed ring with a normed 𝕜-algebra structure.","φ has derivative φ' at z.","ψ has derivative ψ' at z."]),
M("M002","ContDiffAt.isSymmSndFDerivAt","For any nontrivially normed field 𝕜, normed additive commutative groups X,Z with normed 𝕜-vector-space structures, map φ:X→Z, point z∈X and smoothness order ℓ∈WithTop(N∞): if φ is C^ℓ at z and minSmoothness(𝕜,2)≤ℓ, then its second Fréchet derivative is symmetric: for all v,w∈X, D(Dφ)(z)[v][w]=D(Dφ)(z)[w][v]. The minimum smoothness is 2 over R or C and analytic order ω otherwise; D denotes the total Fréchet derivative, zero when no derivative exists.",[b("𝕜","nontrivially normed field"),b("X","normed additive commutative group and normed 𝕜-space"),b("Z","normed additive commutative group and normed 𝕜-space"),b("φ","map X→Z"),b("z","point of X"),b("ℓ","element of WithTop(N∞)"),b("v","vector in X"),b("w","vector in X")],["The field and both normed spaces have the stated structures.","φ is C^ℓ at z.","minSmoothness(𝕜,2)≤ℓ."]),
M("M003","Continuous.integrable_of_hasCompactSupport","Let X carry a measurable structure and a topology with every open set measurable, let Z be a normed additive commutative group, let μ be a measure on X finite on compact sets, and let φ:X→Z. If φ is continuous and the closure of {z∈X:φ(z)≠0} is compact (HasCompactSupport), then φ is Bochner integrable with respect to μ.",[b("X","topological measurable space with measurable open sets"),b("Z","normed additive commutative group"),b("μ","measure on X finite on compact sets"),b("φ","map X→Z"),b("z","point of X")],["X and Z carry the stated structures; μ is finite on compact sets.","φ is continuous.","φ has compact support."]),
M("M004","MeasureTheory.tendsto_integral_filter_of_dominated_convergence","Let X be a measurable space, μ a measure on X, Z a normed additive commutative group and normed real vector space, I an index type and l a countably generated filter on I. Let Φ:I→X→Z, φ:X→Z and β:X→R. Suppose eventually along l the functions Φ(i,·) are almost everywhere strongly measurable; eventually along l, |Φ(i,z)|≤β(z) for μ-almost every z; β is μ-integrable; and for μ-almost every z, Φ(i,z) tends along l to φ(z). Then ∫_X Φ(i,z) dμ tends along l to ∫_X φ(z) dμ.",[b("X","measurable space"),b("μ","measure on X"),b("Z","normed additive commutative group and normed real vector space"),b("I","index type"),b("l","filter on I"),b("Φ","map I→X→Z"),b("φ","map X→Z"),b("β","map X→R"),b("i","element of I"),b("z","point of X")],["X, μ and Z carry the stated structures and l is countably generated.","Eventually Φ(i,·) is μ-almost everywhere strongly measurable.","Eventually |Φ(i,z)|≤β(z) for μ-almost every z.","β is μ-integrable.","For μ-almost every z, Φ(i,z) tends to φ(z) along l."]),
M("M005","norm_image_sub_le_of_norm_deriv_le_segment","Let Z be a normed additive commutative group and normed real vector space, φ:R→Z and a,b,K∈R. If φ is differentiable on [a,b] and |derivWithin φ [a,b] (z)|≤K for every z∈[a,b), then for every z∈[a,b], |φ(z)−φ(a)|≤K(z−a). Here derivWithin is the one-dimensional derivative along the interval, with the total-derivative convention.",[b("Z","normed additive commutative group and normed real vector space"),b("φ","map R→Z"),b("a","real"),b("b","real"),b("K","real"),b("z","real")],["Z has the stated real normed-space structures.","φ is differentiable on [a,b].","The norm of derivWithin φ [a,b] is at most K on [a,b)."]),
M("M006","intervalIntegral.integral_deriv_eq_sub","Let Z be a complete normed additive commutative group and normed real vector space, φ:R→Z and a,b∈R. If φ is differentiable at every z in the unordered closed interval between a and b, and its derivative is interval integrable for Lebesgue measure between a and b, then the oriented interval integral ∫_a^b φ'(z) dz equals φ(b)−φ(a). Interval integrability means integrability on the unordered half-open interval; for a≤b the oriented integral is the Lebesgue integral over (a,b].",[b("Z","complete normed additive commutative group and normed real vector space"),b("φ","map R→Z"),b("a","real"),b("b","real"),b("z","real")],["Z has the stated complete real normed-space structures.","φ is differentiable at each point between the endpoints, inclusive.","Its derivative is interval integrable between a and b."]),
M("M007","MeasureTheory.integral_prod","Let X,Y be measurable spaces, μ,ν measures on them which are s-finite, and Z a normed additive commutative group and normed real vector space. For any φ:X×Y→Z integrable for μ×ν, ∫_{X×Y} φ d(μ×ν)=∫_X(∫_Y φ(z,w) dν(w)) dμ(z).",[b("X","measurable space"),b("Y","measurable space"),b("μ","s-finite measure on X"),b("ν","s-finite measure on Y"),b("Z","normed additive commutative group and normed real vector space"),b("φ","map X×Y→Z"),b("z","point of X"),b("w","point of Y")],["The measurable spaces, s-finite measures and real normed codomain have the stated structures.","φ is integrable for μ×ν."]),
M("M009","IsCompact.exists_bound_of_continuousOn","For a topological space X, a seminormed additive group Z, a set K⊂X and a map φ:X→Z, compactness of K and continuity of φ on K imply that there exists a real L such that |φ(z)|≤L for every z∈K.",[b("X","topological space"),b("Z","seminormed additive group"),b("K","subset of X"),b("φ","map X→Z"),b("L","existential real"),b("z","point of X")],["X is topological and Z is a seminormed additive group.","K is compact.","φ is continuous on K."]),
M("M010","Real.volume_Icc_pi","For any finite type I and functions a,b:I→R, the product Lebesgue measure of the coordinate box {z:I→R:∀i, a(i)≤z(i)≤b(i)} is ∏_{i∈I} ofReal(b(i)−a(i)), where ofReal maps a real to its nonnegative part in the extended nonnegative reals.",[b("I","finite type"),b("a","map I→R"),b("b","map I→R"),b("z","map I→R"),b("i","element of I")],["I is a finite type with its finite enumeration."]),
M("M011","MeasureTheory.measurePreserving_piEquivPiSubtypeProd","For a finite type I, a family of measurable spaces X_i with sigma-finite measures μ_i, and a decidable predicate p on I, the measurable coordinate-restriction equivalence z↦(z restricted to {i:p(i)},z restricted to {i:¬p(i)}) preserves the product measure: the pushforward of ∏_{i∈I}μ_i is (∏_{i:p(i)}μ_i)×(∏_{i:¬p(i)}μ_i).",[b("I","finite type"),b("X_i","family of measurable spaces indexed by I"),b("μ_i","family of sigma-finite measures on X_i"),b("p","decidable predicate on I"),b("z","element of the product of the X_i"),b("i","element of I")],["I is finite; the X_i are measurable spaces.","Every μ_i is sigma-finite.","p is decidable."]),
M("M012","MeasureTheory.integral_finsetSum","For a measurable space X, measure μ, normed additive commutative group Z with a normed real vector-space structure, an index type I, finite subset s of I and family φ:I→X→Z, if φ(i,·) is μ-integrable for every i∈s, then ∫_X sum_{i∈s}φ(i,z) dμ(z)=sum_{i∈s}∫_X φ(i,z) dμ(z).",[b("X","measurable space"),b("μ","measure on X"),b("Z","normed additive commutative group and normed real vector space"),b("I","type"),b("s","finite subset of I"),b("φ","map I→X→Z"),b("i","element of I"),b("z","point of X")],["X, μ and Z have the stated structures and s is finite.","Every φ(i,·) with i∈s is μ-integrable."]),
