M("M016","MeasureTheory.MeasurePreserving.integral_comp","For measurable spaces X,Y with measures μ,ν, a normed additive commutative group Z with a normed real vector-space structure, and map χ:X→Y, if χ preserves μ and ν (it is measurable and its pushforward of μ equals ν) and χ is a measurable embedding, then for every φ:Y→Z, ∫_X φ(χ(z)) dμ(z)=∫_Y φ(w) dν(w). No integrability hypothesis is required for this total Bochner integral identity.",[b("X","measurable space"),b("Y","measurable space"),b("μ","measure on X"),b("ν","measure on Y"),b("Z","normed additive commutative group and normed real vector space"),b("χ","map X→Y"),b("φ","map Y→Z"),b("z","point of X"),b("w","point of Y")],["The measurable spaces, measures and real normed codomain have the stated structures.","χ preserves μ and ν.","χ is a measurable embedding."]),
M("M017","MeasureTheory.measurePreserving_piUnique","For any finite type I with a unique element i0, any family of measurable spaces X_i and measures μ_i, the evaluation measurable equivalence z↦z(i0) from ∏_{i∈I} X_i to X_i0 preserves the product measure and μ_i0.",[b("I","finite type with a unique element"),b("i0","unique element of I"),b("X_i","family of measurable spaces indexed by I"),b("μ_i","family of measures on X_i"),b("z","element of the product of the X_i"),b("i","element of I")],["I is finite with a unique element; every X_i is measurable and every μ_i is a measure on X_i."])
);
