s("S001","Fix t0>0. N002 supplies integrability of e and every derivative product at this time. N004 gives E'(t0)=∫_V e_t(x,t0)dx. N003 gives e_t=2A+2sum_{j=1}^n B_j pointwise.",["N002","N003","N004"],[],[...gg,"t0"],[f("F001","E'(t0)=∫_V e_t(x,t0)dx, e_t(·,t0)=2A(·,t0)+2sum_{j=1}^n B_j(·,t0), and all these scalar sections and each T_j(·,t0) are integrable.",[...gg,"t0"],[{symbol:"x",type:"point of V"}])]),
