app("A005","M013","S003","Set φ=A(·,t0), ψ=−sum_j T_j(·,t0), X=V, μ=dx, Z=R.",["All spaces and measures are the stated real Lebesgue ones.","F001 supplies integrability of A.","F001 supplies integrability of all T_j, hence their negative finite sum."]),
app("A006","M014","S003","Use 𝕜=Z=R, μ=dx, c=−1 and φ=sum_j T_j(·,t0), and c=2 for the combined integrand A−sum_j T_j.",["All the required structures and scalar-action compatibility are those of R."]),
app("A007","M005","S005","Set Z=R, φ=the total extension of E agreeing with it at positive times, bound K=0, a=s,b=t if s<t and a=t,b=s otherwise, evaluating at b.",["R has its real normed-vector-space structures.","F004 gives differentiability at every point of each positive closed interval, hence differentiability on it.","F004 gives ordinary derivative zero; on either nondegenerate interval the within derivative agrees with it, so its norm is at most zero."])
